using System.Windows; using System.Windows.Controls; using System.Windows.Threading; using FFPerformanceEngine.Core.Models; namespace FFPerformanceEngine.App.Pages; public partial class HomePage : UserControl { private readonly DispatcherTimer _timer = new(){Interval=TimeSpan.FromSeconds(1)}; public HomePage(){InitializeComponent();Loaded+=OnLoaded;Unloaded+=(_,_)=>_timer.Stop();_timer.Tick+=(_,_)=>RefreshSystemMetrics();} private void OnLoaded(object sender,RoutedEventArgs e){var env=App.Services.Environment.Capture();ReadyTitle.Text=env.BlueStacksDetected?"Pronto para otimizar":"BlueStacks não detectado";ReadySubtitle.Text=env.BlueStacksDetected?"Ambiente detectado. Use Optimize para medir e validar um perfil.":"Instale/inicie o BlueStacks para liberar medição e tuning.";OsBadge.Text=$"● {env.WindowsDescription}";BlueStacksBadge.Text=env.BlueStacksDetected?"● BlueStacks detectado":"○ BlueStacks ausente";GameBadge.Text=env.ActiveGame==GameKind.None?"○ FF / FF MAX aguardando seleção":$"● {env.ActiveGame}";GuardianValue.Text=App.Services.Settings.GuardianEnabled?$"● Ativo · {App.Services.Settings.GuardianMode}":"○ Desativado";RefreshSystemMetrics();_timer.Start();} private void RefreshSystemMetrics(){var sample=App.Services.Telemetry.CaptureSystemSample();CpuValue.Text=sample.CpuPercent is double cpu?$"{cpu:0}% CPU":"CPU —";MemoryValue.Text=sample.MemoryUsedGb is double used&&sample.MemoryTotalGb is double total?$"{used:0.0} / {total:0.0} GB RAM":"Memória indisponível";} private async void Optimize_Click(object sender,RoutedEventArgs e){var sample=await App.Services.PresentMon.CaptureAsync(TimeSpan.FromSeconds(8));if(sample is null){FpsHint.Text=App.Services.PresentMon.FindExecutable() is null?"Instale PresentMon em Settings/Tools para medir FPS.":"Inicie o BlueStacks para capturar FPS.";return;}FpsValue.Text=$"{sample.Fps:0}";LowValue.Text=sample.OnePercentLow is double low?$"{low:0}":"—";LatencyValue.Text=sample.LatencyMs is double latency?$"{latency:0.0} ms":"—";FpsHint.Text="Medição PresentMon validada";} }